function analysis() { return memberPage('Members / Desk Analysis', 'Analysis.', 'Newest desk-style notes: bias, invalidation, and journal logic.', `<div class="analysis-feed"><article><time datetime="2026-09-20">2026.09.20</time><div><h2>NAS100 / structure before entry</h2><p><b>Bias:</b> Placeholder bullish continuation. <b>Invalidation:</b> Level breaks and holds below. <b>Journal:</b> Wait for confirmation; no chase.</p></div></article><article><time datetime="2026-09-18">2026.09.18</time><div><h2>GOLD / protect the downside</h2><p><b>Bias:</b> Placeholder range. <b>Invalidation:</b> Range expansion against the idea. <b>Journal:</b> Smaller size while conditions are unclear.</p></div></article><article><time datetime="2026-09-16">2026.09.16</time><div><h2>US30 / levels before noise</h2><p><b>Bias:</b> Placeholder sell setup. <b>Invalidation:</b> Reclaim of the marked level. <b>Journal:</b> The level is the decision, not the screenshot.</p></div></article></div><div class="member-note"><strong>Analysis standard</strong><span>These are educational examples, not signals or recommendations. Make your own decisions in your own account.</span></div>`); }
function rules() { return memberPage('Members / Operating Standard', 'Rules.', 'The standard that keeps access useful.', `<div class="rules-page-grid"><div><h2>Desk rules</h2><ol><li>Process over impulse</li><li>No trade without bias + invalidation</li><li>Risk fixed before entry</li><li>Small size until consistency shows</li><li>Journal every trade</li><li>No revenge trading</li><li>No sharing paid materials</li><li>Your account only</li><li>Questions in proper channels</li><li>Break rules - access review</li></ol></div><div><h2>Risk policy</h2><ul><li>Risk 0.5%-1% per trade while learning</li><li>Tiny dollar risk on small accounts</li><li>No all-in</li><li>No martingale</li><li>Max daily loss: 2R then stop</li></ul><p class="member-note">Capital protection is part of the process.</p></div></div>`); }
function join() { return `<section class="page join-page">${header('Access / Key → Seat → Process', 'Choose your seat.', 'Start with the signal. Choose the lane. Checkout is handled securely by Stripe.')}<div class="onboarding-products">${onboardingTierCards()}</div><p class="onboarding-seat-note">Delivered online. Education and access only — not investment advice. No guaranteed returns. You trade your own account.</p><a class="terms-link" href="#/terms">Read Desk Access Terms ↗</a></section>`; }
function terms() { return `<section class="page terms-page"><div class="eyebrow">Legal / Desk access</div><h1 class="display page-title">Desk Access Terms</h1><p class="terms-updated">Gami Boyz / Kurogami Operator Network<br>Last updated: September 16, 2026</p><div class="terms-content"><section><h2>Agreement</h2><p>By paying for or accessing Desk Access, Operator Seat, or Capital Partner Seat, you agree to these Terms.</p></section><section><h2>What you are buying</h2><p>You are purchasing education, process training, and operator network access related to market execution frameworks.</p><p><strong>This is NOT:</strong> investment advice; portfolio management; a fund or pooled investment; a brokerage relationship; a promise of profit or income; or a securities offering.</p><p>Any trading you do is solely in your own accounts, at your own risk.</p></section><section><h2>Tiers</h2><p><strong>Desk Access ($1,500):</strong> digital access to Kurogami desk tools, process education, risk and watchlist methodology, and 30 days of guided access. Delivered online.</p><p><strong>Operator Seat ($5,000):</strong> full operator access including Desk Access benefits, onboarding, setup reviews, capital allocation framework education, operator network access, and priority sessions as available. Delivered online.</p><p><strong>Capital Partner Seat ($15,000 or $25,000):</strong> highest access tier including Operator Seat benefits, higher-touch access, priority onboarding, portfolio structuring education intro, and priority infrastructure and intake consideration. Delivered online.</p><p>No tier includes automatic management of your funds. Any separate capital arrangement requires a separate written agreement.</p></section><section><h2>Payment &amp; access</h2><p>Full payment is required before access. Access begins only after payment is confirmed.</p></section><section><h2>Refunds</h2><p>All sales are final once access or materials are delivered, except where required by law. Chargebacks after access is granted are a breach of these Terms.</p></section><section><h2>Risk disclosure</h2><p>Markets involve substantial risk of loss. You may lose some or all capital. Past results do not guarantee future results. You confirm you can afford the fee and any capital you choose to trade, and that you will not trade money you cannot afford to lose.</p></section><section><h2>No performance guarantee</h2><p>We make no guarantee of profits, income, win rate, returns, or account growth. Examples and screenshots are illustrative only.</p></section><section><h2>Your responsibilities</h2><p>You agree to follow published desk rules, protect your credentials, not share paid materials, act in good faith in community spaces, and make your own independent decisions.</p></section><section><h2>Intellectual property</h2><p>All materials, frameworks, branding, and content remain our property. You receive a limited personal-use license only. No resale or republication without written permission.</p></section><section><h2>Conduct</h2><p>We may remove access for abuse, scams, leaking materials, misrepresentation, or harmful solicitation. No refund if removed for cause.</p></section><section><h2>Third parties</h2><p>Brokers, exchanges, TradingView, Telegram, Instagram, and other tools are third parties. We are not responsible for their outages, losses, or policies.</p></section><section><h2>Limitation of liability</h2><p>To the maximum extent permitted by law, our total liability under these Terms is limited to the fee you paid for the current access term. We are not liable for trading losses or indirect damages.</p></section><section><h2>Term</h2><p>Desk Access defaults to 30 days from payment unless otherwise stated at checkout. Higher tiers follow the access window stated at purchase. Continued access requires renewal or written extension.</p></section><section><h2>Separate capital deals</h2><p>Any profit-share, managed execution, or capital allocation arrangement is outside these Terms and requires a separate signed agreement.</p></section><section><h2>Changes</h2><p>We may update these Terms. Continued use after updates constitutes acceptance of the revised Terms.</p></section><section><h2>Contact</h2><p>Questions: DM DESK on Instagram or contact via the site access channel.</p></section><p class="terms-acknowledgment">By completing checkout or accessing any tier, you acknowledge that you have read, understood, and agree to these Terms.</p></div></section>`; }
